import json, subprocess, sys
def gws(*args):
    out = subprocess.run(["gws","drive","files",*args],capture_output=True,text=True,cwd="/Users/kristinarash/.claude/jobs/010c576b/tmp").stdout
    out = "\n".join(l for l in out.splitlines() if not l.startswith("Using keyring"))
    return json.loads(out) if out.strip() else {}
def get(fid):
    return gws("get","--params",json.dumps({"fileId":fid,"fields":"id,name,parents,trashed,createdTime,modifiedTime","supportsAllDrives":True}))
